namespace ShipmentTracker.Shared;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string SenderName { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public string? Notes { get; set; }
}

public class ShipmentUpdateDto
{
    public ShipmentStatus Status { get; set; }
    public string? Notes { get; set; }
}

public class TrackingResultDto
{
    public string TrackingNumber { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public List<ShipmentEventDto> Events { get; set; } = [];
}

public class ShipmentEventDto
{
    public DateTime TimestampUtc { get; set; }
    public string Description { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;
using ShipmentTracker.Shared;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }

    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }

    [MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(200)]
    public string SenderName { get; set; } = string.Empty;

    public double WeightKg { get; set; }

    [MaxLength(500)]
    public string? Notes { get; set; }

    // Owner of this shipment (the customer who can track it)
    public string? CustomerUserId { get; set; }

    public List<ShipmentEvent> Events { get; set; } = [];
}

public class ShipmentEvent
{
    public int Id { get; set; }
    public int ShipmentId { get; set; }
    public Shipment Shipment { get; set; } = null!;
    public DateTime TimestampUtc { get; set; }

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Location { get; set; } = string.Empty;
}

