using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Shared;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        // GET all shipments (dispatchers only)
        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAtUtc)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    CreatedAtUtc = s.CreatedAtUtc,
                    EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                    ActualDeliveryUtc = s.ActualDeliveryUtc,
                    RecipientName = s.RecipientName,
                    SenderName = s.SenderName,
                    WeightKg = s.WeightKg,
                    Notes = s.Notes
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // GET shipments for current customer
        group.MapGet("/my", [Authorize] async (ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var userId = userManager.GetUserId(ctx.User);
            var shipments = await db.Shipments
                .Where(s => s.CustomerUserId == userId)
                .OrderByDescending(s => s.CreatedAtUtc)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    CreatedAtUtc = s.CreatedAtUtc,
                    EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                    ActualDeliveryUtc = s.ActualDeliveryUtc,
                    RecipientName = s.RecipientName,
                    SenderName = s.SenderName,
                    WeightKg = s.WeightKg,
                    Notes = s.Notes
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Track a shipment by tracking number (public)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Include(s => s.Events)
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null)
                return Results.NotFound();

            var result = new TrackingResultDto
            {
                TrackingNumber = shipment.TrackingNumber,
                Status = shipment.Status,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                CreatedAtUtc = shipment.CreatedAtUtc,
                EstimatedDeliveryUtc = shipment.EstimatedDeliveryUtc,
                ActualDeliveryUtc = shipment.ActualDeliveryUtc,
                RecipientName = shipment.RecipientName,
                Events = shipment.Events
                    .OrderByDescending(e => e.TimestampUtc)
                    .Select(e => new ShipmentEventDto
                    {
                        TimestampUtc = e.TimestampUtc,
                        Description = e.Description,
                        Location = e.Location
                    })
                    .ToList()
            };

            return Results.Ok(result);
        });

        // POST create a new shipment (dispatcher)
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (ShipmentDto dto, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = ShipmentStatus.Pending,
                CreatedAtUtc = DateTime.UtcNow,
                EstimatedDeliveryUtc = dto.EstimatedDeliveryUtc,
                RecipientName = dto.RecipientName,
                SenderName = dto.SenderName,
                WeightKg = dto.WeightKg,
                Notes = dto.Notes
            };

            shipment.Events.Add(new ShipmentEvent
            {
                TimestampUtc = DateTime.UtcNow,
                Description = "Shipment created",
                Location = dto.Origin
            });

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            dto.Id = shipment.Id;
            dto.TrackingNumber = shipment.TrackingNumber;
            dto.Status = shipment.Status;
            dto.CreatedAtUtc = shipment.CreatedAtUtc;

            return Results.Created($"/api/shipments/{shipment.Id}", dto);
        });

        // PUT update shipment status (dispatcher)
        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, ShipmentUpdateDto update, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            shipment.Status = update.Status;
            if (update.Status == ShipmentStatus.Delivered)
                shipment.ActualDeliveryUtc = DateTime.UtcNow;

            db.ShipmentEvents.Add(new ShipmentEvent
            {
                ShipmentId = id,
                TimestampUtc = DateTime.UtcNow,
                Description = $"Status changed to {update.Status}",
                Location = update.Notes ?? ""
            });

            if (update.Notes is not null)
                shipment.Notes = update.Notes;

            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Shared;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();

        await db.Database.MigrateAsync();

        // Create roles
        foreach (var role in new[] { "Dispatcher", "Customer" })
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }

        // Create demo dispatcher
        if (await userManager.FindByEmailAsync("dispatcher@shiptrack.com") is null)
        {
            var dispatcher = new ApplicationUser
            {
                UserName = "dispatcher@shiptrack.com",
                Email = "dispatcher@shiptrack.com",
                EmailConfirmed = true
            };
            await userManager.CreateAsync(dispatcher, "Dispatch1!");
            await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
        }

        // Create demo customer
        var customer = await userManager.FindByEmailAsync("customer@example.com");
        if (customer is null)
        {
            customer = new ApplicationUser
            {
                UserName = "customer@example.com",
                Email = "customer@example.com",
                EmailConfirmed = true
            };
            await userManager.CreateAsync(customer, "Customer1!");
            await userManager.AddToRoleAsync(customer, "Customer");
        }

        // Seed shipments if empty
        if (!await db.Shipments.AnyAsync())
        {
            var shipments = new List<Shipment>
            {
                new()
                {
