arguments.file_text:
@page "/track/{TrackingNumber}"
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h2>📍 Track Shipment</h2>

<div class="mb-3">
    <div class="input-group" style="max-width:500px;">
        <input type="text" class="form-control" placeholder="Tracking number"
               @bind="searchNumber" @bind:event="oninput"
               @onkeyup="HandleKeyUp" />
        <button class="btn btn-primary" @onclick="Search">Search</button>
    </div>
</div>

@if (loading)
{
    <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
    </div>
}
else if (error is not null)
{
    <div class="alert alert-warning">@error</div>
}
else if (result is not null)
{
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@result.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(result.Status) fs-6">@result.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @result.Origin</p>
                    <p><strong>To:</strong> @result.Destination</p>
                    <p><strong>Recipient:</strong> @result.RecipientName</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Created:</strong> @result.CreatedAtUtc.ToString("g") UTC</p>
                    @if (result.EstimatedDeliveryUtc.HasValue)
                    {
                        <p><strong>Estimated Delivery:</strong> @result.EstimatedDeliveryUtc.Value.ToString("g") UTC</p>
                    }
                    @if (result.ActualDeliveryUtc.HasValue)
                    {
                        <p><strong>Delivered:</strong> @result.ActualDeliveryUtc.Value.ToString("g") UTC</p>
                    }
                </div>
            </div>
        </div>
    </div>

    @if (result.Events.Count > 0)
    {
        <h5>Shipment History</h5>
        <div class="list-group">
            @foreach (var evt in result.Events)
            {
                <div class="list-group-item">
                    <div class="d-flex justify-content-between">
                        <strong>@evt.Description</strong>
                        <small class="text-muted">@evt.TimestampUtc.ToString("g") UTC</small>
                    </div>
                    <small>📍 @evt.Location</small>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";

    private string searchNumber = "";
    private TrackingResultDto? result;
    private bool loading;
    private string? error;

    [Inject] private NavigationManager Navigation { get; set; } = default!;

    protected override async Task OnParametersSetAsync()
    {
        searchNumber = TrackingNumber;
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            await LoadTracking(TrackingNumber);
        }
    }

    private async Task Search()
    {
        if (!string.IsNullOrWhiteSpace(searchNumber))
        {
            Navigation.NavigateTo($"track/{Uri.EscapeDataString(searchNumber.Trim())}");
        }
    }

    private void HandleKeyUp(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            _ = Search();
    }

    private async Task LoadTracking(string trackingNum)
    {
        loading = true;
        error = null;
        result = null;

        try
        {
            var response = await Http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNum)}");
            if (response.IsSuccessStatusCode)
            {
                result = await response.Content.ReadFromJsonAsync<TrackingResultDto>();
            }
            else
            {
                error = "Shipment not found. Please check the tracking number.";
            }
        }
        catch
        {
            error = "Unable to load tracking information. Please try again.";
        }
        finally
        {
            loading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>🚚 Dispatcher Dashboard</h2>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div>
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or recipient..."
                   @bind="filterText" @bind:event="oninput" style="min-width:300px;" />
            <select class="form-select" style="max-width:180px;" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
    </div>
    <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Recipient</label>
                    <input class="form-control" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Sender</label>
                    <input class="form-control" @bind="newShipment.SenderName" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Weight (kg)</label>
                    <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery (UTC)</label>
                    <input type="datetime-local" class="form-control" @bind="estimatedDelivery" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Notes</label>
                    <input class="form-control" @bind="newShipment.Notes" />
                </div>
            </div>
            <button class="btn btn-primary mt-2" @onclick="CreateShipment" disabled="@creating">
                @(creating ? "Creating..." : "Create")
            </button>
            @if (createError is not null)
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (loading)
{
    <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
    </div>
}
else if (loadError is not null)
{
    <div class="alert alert-danger">@loadError</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Status</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Weight</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><a href="track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td>@s.WeightKg kg</td>
