{"file_text": "@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>🚚 Dispatcher Dashboard</h2>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div>
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or recipient..."
                   @bind="filterText" @bind:event="oninput" style="min-width:300px;" />
            <select class="form-select" style="max-width:180px;" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
    </div>
    <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Recipient</label>
                    <input class="form-control" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Sender</label>
                    <input class="form-control" @bind="newShipment.SenderName" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Weight (kg)</label>
                    <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery (UTC)</label>
                    <input type="datetime-local" class="form-control" @bind="estimatedDelivery" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Notes</label>
                    <input class="form-control" @bind="newShipment.Notes" />
                </div>
            </div>
            <button class="btn btn-primary mt-2" @onclick="CreateShipment" disabled="@creating">
                @(creating ? "Creating..." : "Create")
            </button>
            @if (createError is not null)
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (loading)
{
    <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
    </div>
}
else if (loadError is not null)
{
    <div class="alert alert-danger">@loadError</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Status</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Weight</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><a href="track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td>@s.WeightKg kg</td>
                        <td>@(s.EstimatedDeliveryUtc?.ToString("g") ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <div class="btn-group btn-group-sm">
                                    <select class="form-select form-select-sm" style="width:140px;"
                                            value="@s.Status"
                                            @onchange="e => UpdateStatus(s, e)">
                                        @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@st" selected="@(st == s.Status)">@st</option>
                                        }
                                    </select>
                                </div>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string? loadError;

    private string filterText = "";
    private string statusFilter = "";

    private bool showCreateForm;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDelivery;
    private bool creating;
    private string? createError;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var sf) && s.Status != sf)
            return false;

        if (!string.IsNullOrWhiteSpace(filterText))
        {
            var f = filterText.Trim();
            return s.TrackingNumber.Contains(f, StringComparison.OrdinalIgnoreCase)
                || s.Destination.Contains(f, StringComparison.OrdinalIgnoreCase)
                || s.RecipientName.Contains(f, StringComparison.OrdinalIgnoreCase)
                || s.Origin.Contains(f, StringComparison.OrdinalIgnoreCase);
        }
        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        loadError = null;
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
        }
        catch (Exception ex)
        {
            loadError = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private async Task CreateShipment()
    {
        creating = true;
        createError = null;
        try
        {
            newShipment.EstimatedDeliveryUtc = estimatedDelivery.HasValue
                ? DateTime.SpecifyKind(estimatedDelivery.Value, DateTimeKind.Utc)
                : null;

            var response = await Http.PostAsJsonAsync("api/shipments", newShipment);
            if (response.IsSuccessStatusCode)
            {
                showCreateForm = false;
                newShipment = new();
                estimatedDelivery = null;
                await LoadShipments();
            }
            else
            {
                createError = "Failed to create shipment.";
            }
        }
        catch (Exception ex)
        {
            createError = ex.Message;
        }
        finally
        {
            creating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var update = new ShipmentUpdateDto { Status = newStatus };
            var response = await Http.PutAsJsonAsync($"api/shipments/{shipment.Id}/status", update);
            if (response.IsSuccessStatusCode)
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.ActualDeliveryUtc = DateTime.UtcNow;
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
