@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>My Shipments</PageTitle>

<h2>📦 My Shipments</h2>

@if (loading)
{
    <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
    </div>
}
else if (error is not null)
{
    <div class="alert alert-danger">@error</div>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">You have no shipments yet.</div>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter shipments..."
               @bind="filterText" @bind:event="oninput" style="max-width:400px;" />
    </div>

    <div class="row">
        @foreach (var s in FilteredShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <a href="track/@s.TrackingNumber">@s.TrackingNumber</a>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Recipient:</strong> @s.RecipientName</p>
                        @if (s.EstimatedDeliveryUtc.HasValue)
                        {
                            <p class="mb-1">
                                <strong>Est. Delivery:</strong> @s.EstimatedDeliveryUtc.Value.ToString("g") UTC
                            </p>
                        }
                        @if (s.ActualDeliveryUtc.HasValue)
                        {
                            <p class="mb-1 text-success">
                                <strong>Delivered:</strong> @s.ActualDeliveryUtc.Value.ToString("g") UTC
                            </p>
                        }
                    </div>
                    <div class="card-footer">
                        <a href="track/@s.TrackingNumber" class="btn btn-sm btn-outline-primary">Track Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string? error;
    private string filterText = "";

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (string.IsNullOrWhiteSpace(filterText)) return true;
        var f = filterText.Trim();
        return s.TrackingNumber.Contains(f, StringComparison.OrdinalIgnoreCase)
            || s.Destination.Contains(f, StringComparison.OrdinalIgnoreCase)
            || s.RecipientName.Contains(f, StringComparison.OrdinalIgnoreCase);
    });

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my") ?? [];
        }
        catch (Exception ex)
        {
            error = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

